                        source: state,
                        targets: [],
                        transitionIndex: 1,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .doneInvokeWatch {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.after)],
                        transitionIndex: 2,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
        default:
            break
        }
        return nil
    }

    /// Runs one transition's executable content (W3C SCXML 3.13), between the
    /// microstep's exits and its entries.
    public func executeTransitionContent(source: StaticInvokeHybridSavedState, transitionIndex: Int, engine: Engine<StaticInvokeHybridSavedPolicy>) {
        switch source {
        case .working:
            switch transitionIndex {
            case 0:
                // W3C SCXML 4.9: a transition's content is one block; an error ends it.
                sceBlock: do {


                if ({ () -> Bool in let sceFailure = Failure(); let sceValue: UInt32 = Checked.add(sceFailure, self.vBase, 1); if sceFailure.failed { return true }; self.vBase = sceValue; return false }()) {
                    break sceBlock  // W3C SCXML 4.9: the error ends the block
                }

                }
            case 1:
                // W3C SCXML 4.9: a transition's content is one block; an error ends it.
                sceBlock: do {


                if ({ () -> Bool in let sceFailure = Failure(); let sceValue: String = Checked.bounded(sceFailure, "static_hybrid_holder.scxml", capacity: 48); if sceFailure.failed { return true }; self.vPick = sceValue; return false }()) {
                    break sceBlock  // W3C SCXML 4.9: the error ends the block
                }

                }
            case 2:
                // W3C SCXML 4.9: a transition's content is one block; an error ends it.
                sceBlock: do {


                if ({ () -> Bool in let sceFailure = Failure(); let sceValue: UInt32 = Checked.add(sceFailure, self.vCompleted, 1); if sceFailure.failed { return true }; self.vCompleted = sceValue; return false }()) {
                    break sceBlock  // W3C SCXML 4.9: the error ends the block
                }

                }
            default:
                break
            }
        default:
            break
        }
    }}


// ======================================================================
// Saved state (docs/adr/0045)
// ======================================================================

extension StaticInvokeHybridSavedPolicy: SavedPolicy {
    /// What a saved state of this document is bound to: a digest the generator computes of every
    /// state with its kind and parent and every variable with its type, not of the document's text,
    /// so a later build whose guards, actions or comments changed restores it and one that renamed,
    /// re-typed or moved something a saved state names refuses it.
    public static var savedShape: SavedShape {
        SavedShape(
            first: "f86ee6b2a368019b8e1fdad9e63e1a2c94c4fe8037e7a0815c468753bfd23715",
            revised: "f58e4e0ef0bd5c4afde2c75a7f3bd909a92ae6b85dc2f2e96a794adb38e370d9",
            format2First: "f86ee6b2a368019b8e1fdad9e63e1a2c94c4fe8037e7a0815c468753bfd23715",
            format2Revised: "f58e4e0ef0bd5c4afde2c75a7f3bd909a92ae6b85dc2f2e96a794adb38e370d9")
    }

    /// Every variable, by document id, in declaration order, each as a saved state holds it: the
    /// machine's own included, and not only the ones it publishes.
    public func savedVariables() -> [SavedEntry<JSONValue>] {
        [
            SavedEntry("pick", SavedValues.of(vPick)),
            SavedEntry("base", SavedValues.of(vBase)),
            SavedEntry("completed", SavedValues.of(vCompleted)),
        ]
    }

    /// Reads and judges every variable `saved` holds, the type each is held to and the bound of a
    /// text, and changes none: what it returns writes them, and cannot fail.
    public func readSavedVariables(from saved: SavedState) throws -> () -> Void {
        let value0 = try SavedValues.string(try saved.variable("pick"), "pick", capacity: 48)
        let value1 = try SavedValues.uint32(try saved.variable("base"), "base")
        let value2 = try SavedValues.uint32(try saved.variable("completed"), "completed")
        return { [self] in
            self.vPick = value0
            self.vBase = value1
            self.vCompleted = value2
        }
    }

    /// The id the document gives each of its `<invoke type="scxml">`s, in document order.
    public var savedInvokeIDs: [String] {
        ["watch"]
    }

    /// How many times each `<invoke>` has started, which numbers the next start's id.
    public func savedInvokeStarts() -> [SavedEntry<Int64>] {
        var counted: [SavedEntry<Int64>] = []
        if sceInvokeStartsWatch > 0 {
            counted.append(SavedEntry("watch", Int64(sceInvokeStartsWatch)))
        }
        return counted
    }

    /// Every `<invoke>` whose child session is running, each with the child's whole state
    /// (docs/adr/0045). A child that has ended is not running, though its entry stays until its state exits.
    public func savedChildren(wallNowMs: Int64) throws -> [SavedChild] {
        var running: [SavedChild] = []
        if let child = sceInvokeChildWatch, !sceInvokeDoneWatch,
            let slot = activeInvokes["watch"]
        {
            // The slot holds whichever candidate the `srcexpr` named, by what a parent drives it through.
            guard let saving = child as? any SavedChildEngine else {
                throw StateRefusal("the session of 'watch' is one this runtime cannot save")
            }
            // The id the child was started under, which its session id derives from this one's: carried, not
            // computed again.
            running.append(
                SavedChild(
                    id: "watch", start: Int64(sceInvokeStartsWatch),
                    invokeID: String(slot.sessionID.dropFirst(sessionID.count + 1)),
                    document: sceInvokeStemWatch,
                    session: try saving.saveSession(wallNowMs: wallNowMs)))
        }
        return running
    }

    /// The state that holds the `<invoke>` `id`, which a saved state's children and restarts are held to.
    private func savedInvokeOwner(_ id: String) -> StaticInvokeHybridSavedState? {
        switch id {
        case "watch": return .working
        default: return nil
        }
    }

    /// Judges the children and the counts of starts `saved` holds and changes nothing; what it returns puts the
    /// children back once this machine stands where it was saved (docs/adr/0045, section 3).
    public func readSavedChildren(from saved: SavedState, engine: Engine<StaticInvokeHybridSavedPolicy>, wallNowMs: Int64) throws -> () -> Void {
        for counted in saved.invokeStarts where savedInvokeOwner(counted.key) == nil {
            throw StateRefusal("invokestarts counts '\(counted.key)', which the document does not invoke")
        }
        func counted(_ id: String) -> Int64 { saved.invokeStarts.first { $0.key == id }?.value ?? 0 }
        // The state that holds an `<invoke>` is one the saved configuration stands in, and no `<invoke>` is listed twice.
        func holder(_ id: String, _ what: String, _ seen: inout Set<String>) throws -> StaticInvokeHybridSavedState {
            guard let owner = savedInvokeOwner(id) else {
                throw StateRefusal("the saved state holds a running child session '\(id)', which this machine does not start")
            }
            guard saved.configuration.contains(getStateName(owner)) else {
                throw StateRefusal("\(what) is '\(id)', whose state the saved configuration does not stand in")
            }
            guard seen.insert(id).inserted else {
                throw StateRefusal("\(what) is '\(id)', which an earlier entry already names")
            }
            return owner
        }
        var seen: Set<String> = []
        var resume: [() -> Void] = []
        var restart: [String] = []
        switch saved.invokes {
        case .resumed(let children):
            for (index, child) in children.enumerated() {
                _ = try holder(child.id, "invokes[\(index)]", &seen)
                if child.start != counted(child.id) {
                    throw StateRefusal(
                        "invokes[\(index)] is start \(child.start) of '\(child.id)', and the session counts \(counted(child.id)) "
                            + "starts of it: a state re-entered cancels the earlier child before it starts the next one")
                }
                // The id the child would be given where it is built, derived from this session's own, which the
                // restore is about to bind.
                let derived = "\(saved.boundSessionID ?? sessionID).\(child.invokeID)"
                if child.session.sessionID != derived {
                    throw StateRefusal(
                        "invokes[\(index)].session's id is '\(child.session.sessionID)', and a child of "
                            + "'\(saved.boundSessionID ?? sessionID)' started under '\(child.invokeID)' is '\(derived)'")
                }
                switch child.id {
                case "watch":
                    resume.append(try sceJudgeSavedChildWatch(child, index, derived, saved.boundSessionID ?? sessionID, engine: engine, wallNowMs: wallNowMs))
                default:
                    break
                }
            }
        case .restarted(let ids):
            for (index, id) in ids.enumerated() {
                _ = try holder(id, "invokes[\(index)]", &seen)
                restart.append(id)
            }
        }
        return { [self] in
            sceInvokeStartsWatch = Int(counted("watch"))
            for put in resume { put() }
            // A format-1 state holds a child by its id alone, so each is started again from its beginning, as
            // entering its state starts it, and last, so what a child sends as it starts stands behind what was
            // already waiting.
            for id in restart {
                switch id {
                case "watch":
                    sceInvokeStartsWatch += 1
                    deferInvoke(&pendingInvokes, PendingInvoke(
                        invokeID: "working.\(sceInvokeStartsWatch).watch",
                        state: .working,
                        documentID: "watch"))
                default:
                    break
                }
            }
            if !restart.isEmpty {
                executePendingInvokes(engine: engine)
            }
        }
    }

    /// Builds the session `<invoke>` `watch` ran as the saved child names it and judges
    /// the state it holds, down to its last grandchild; what it returns resumes it where it stood, in place of
    /// starting it: no `<onentry>` runs, no `<data>` is evaluated and nothing is sent.
    private func sceJudgeSavedChildWatch(
        _ child: SavedChild, _ index: Int, _ childSessionID: String, _ parentSessionID: String,
        engine: Engine<StaticInvokeHybridSavedPolicy>, wallNowMs: Int64
    ) throws -> () -> Void {
        // The candidate the saved child names: whatever `srcexpr` reads now, the child that was running resumes.
        switch child.document {
        case "static_hybrid_watcher":
            let childPolicy = StaticHybridWatcherPolicy()
            let session = InvokedSession(
                policy: childPolicy,
                sessionID: childSessionID,
                queue: ParentEventQueue(parentSessionID: parentSessionID)
            )
            let resumeChild = try session.prepareSavedChild(child.session, index: index, wallNowMs: wallNowMs)
            return { [self] in
                // The child's delayed sends are measured on this machine's clock, as the start of one makes them, and
                // before it is restored, since restoring arms them.
                session.engine.setClock(engine.clock())
                engine.startChildMesh(of: session, invokeID: "watch", document: "static_hybrid_watcher")
                resumeChild()
                activeInvokes["watch"] = ChildSession(
                    sessionID: childSessionID,
                    invokeID: "watch",
                    parentSessionID: sessionID,
                    autoforward: false,
                    finalizeScript: ""
                )
                sceInvokeChildWatch = session
                sceInvokeStemWatch = "static_hybrid_watcher"
                sceInvokeDoneWatch = false
            }
        case "static_hybrid_holder":
            let childPolicy = StaticHybridHolderPolicy()
            let session = InvokedSession(
                policy: childPolicy,
                sessionID: childSessionID,
                queue: ParentEventQueue(parentSessionID: parentSessionID)
            )
            let resumeChild = try session.prepareSavedChild(child.session, index: index, wallNowMs: wallNowMs)
            return { [self] in
                // The child's delayed sends are measured on this machine's clock, as the start of one makes them, and
                // before it is restored, since restoring arms them.
                session.engine.setClock(engine.clock())
                engine.startChildMesh(of: session, invokeID: "watch", document: "static_hybrid_holder")
                resumeChild()
                activeInvokes["watch"] = ChildSession(
                    sessionID: childSessionID,
                    invokeID: "watch",
                    parentSessionID: sessionID,
                    autoforward: false,
                    finalizeScript: ""
                )
                sceInvokeChildWatch = session
                sceInvokeStemWatch = "static_hybrid_holder"
                sceInvokeDoneWatch = false
            }
        default:
            throw StateRefusal("invokes[\(index)] is of '\(child.document)', which 'watch' does not start")
        }
    }
}
